<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Requests\RegisterRequest; use App\Services\AuthService; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException; use Tymon\JWTAuth\Facades\JWTAuth;
class AuthController extends ApiController { public function __construct(private AuthService $auth){} public function register(RegisterRequest $r){return $this->success($this->auth->register($r->validated()));} public function login(Request $r){$d=$r->validate(['phone'=>'required|string','password'=>'required|string']);return $this->success($this->auth->login($d['phone'],$d['password']));} public function logout(){JWTAuth::invalidate(JWTAuth::getToken());return response()->noContent();} public function refresh(Request $r){$d=$r->validate(['refresh_token'=>'required|string']);return $this->success($this->auth->refresh($d['refresh_token']));} public function verify(Request $r){$d=$r->validate(['phone'=>'required','otp'=>'required|digits:6']);$row=\DB::table('verification_tokens')->where('used_at',null)->where('expires_at','>',now())->latest()->get()->first(fn($x)=>Hash::check($d['otp'],$x->token_hash));if(!$row||User::find($row->user_id)->phone!==$d['phone'])throw ValidationException::withMessages(['otp'=>'Invalid or expired OTP.']);$u=User::find($row->user_id);$u->update(['status'=>'ACTIVE']);\DB::table('verification_tokens')->where('id',$row->id)->update(['used_at'=>now()]);return $this->success($this->auth->tokens($u));} public function forgot(Request $r){$d=$r->validate(['phone'=>'required']);$u=User::where('phone',$d['phone'])->first();if($u){$code=(string)random_int(100000,999999);\DB::table('password_reset_tokens')->updateOrInsert(['phone'=>$u->phone],['token_hash'=>Hash::make($code),'expires_at'=>now()->addHour(),'created_at'=>now(),'updated_at'=>now()]);app(\App\Services\OtpProvider::class)->send($u->phone,$code);}return $this->success(['message'=>'If the account exists, reset instructions were sent.','development_otp'=>app()->environment('local','testing')&&$u?$code:null]);} public function reset(Request $r){$d=$r->validate(['phone'=>'required','otp'=>'required|digits:6','password'=>'required|min:8|confirmed']);$row=\DB::table('password_reset_tokens')->where('phone',$d['phone'])->where('expires_at','>',now())->first();if(!$row||!Hash::check($d['otp'],$row->token_hash))throw ValidationException::withMessages(['otp'=>'Invalid or expired reset token.']);User::where('phone',$d['phone'])->update(['password_hash'=>Hash::make($d['password'])]);\DB::table('password_reset_tokens')->where('phone',$d['phone'])->delete();return $this->success(['message'=>'Password reset successfully.']);} }
